const cfg = items[0].json || {};
const missing = [];
const REQUIRED = ['niche','groqApiKey','flikiApiKey','slackWebhook','googleSheetId','uploadPostApiKey','youtubeChannelId'];
for (const f of REQUIRED) {
  if (!cfg[f] || String(cfg[f]).includes('PASTE_')) missing.push(f);
}
const policyIssues = [];
const bindingIssues = Array.isArray(cfg.configBindingIssues) ? cfg.configBindingIssues : [];
if (bindingIssues.length) policyIssues.push('MISSING_BINDINGS');
if (cfg.maintenanceMode) policyIssues.push('MAINTENANCE_MODE');
if (cfg.channelEnabled === false) policyIssues.push('CHANNEL_DISABLED');
if (cfg.channelAllowContent === false) policyIssues.push('CONTENT_DISABLED');
if (cfg.publishEnabled === false || cfg.channelAllowPublish === false) policyIssues.push('PUBLISH_DISABLED');
const globalMode = String(cfg.globalMode || 'LIVE').toUpperCase();
if (globalMode === 'PAUSED') policyIssues.push('GLOBAL_PAUSED');
if (globalMode === 'TEST' && cfg.allowContentInTestMode !== true) policyIssues.push('TEST_MODE_BLOCKS_CONTENT');
return [{
  json: {
    ...cfg,
    configOk: missing.length === 0 && policyIssues.length === 0,
    configError: [
      missing.length ? 'MISSING: ' + missing.join(', ') : '',
      policyIssues.length ? 'POLICY: ' + policyIssues.join(', ') : ''
    ].filter(Boolean).join(' | '),
    runId: cfg.runId || ('run_' + Date.now()),
    startedAt: cfg.startedAt || new Date().toISOString(),
    workflowPackVersion: cfg.workflowPackVersion || 'v24'
  }
}];

const cfg = $('Validate Config').first().json || {};
const norm = (v='') => String(v).trim();
const lower = (v='') => norm(v).toLowerCase();
const avg = (arr=[]) => arr.length ? arr.reduce((a,b)=>a+b,0) / arr.length : 0;
const unique = (arr=[]) => [...new Set(arr.filter(Boolean))];

let rows = [];
try {
  rows = $('Load Past Videos').all().map(i => i.json).filter(r => r.topic || r.Topic || r.title || r.Title);
} catch (e) {}

let ownerNotes = [];
try {
  ownerNotes = $('Load Owner Notes').all().map(i => i.json);
} catch (e) {}

const ownerPriority = { high: 3, medium: 2, low: 1 };
const activeNotes = ownerNotes
  .filter(n => lower(n.status || n.Status || 'active') !== 'done')
  .sort((a,b) => (ownerPriority[lower(b.priority || b.Priority || 'medium')] || 1) - (ownerPriority[lower(a.priority || a.Priority || 'medium')] || 1))
  .slice(0, 6)
  .map(n => `[${String(lower(n.priority || n.Priority || 'medium')).toUpperCase()}] ${norm(n.note || n.Note || '')}`)
  .filter(Boolean);

function inferMixBucket(r) {
  const lane = lower(r.contentLane || r.ContentLane || '');
  const fmt = lower(r.selectedFormat || r.format || r.videoFormat || r.VideoFormat || '');
  if (/comparison|free|versus|vs|winner/.test(lane + ' ' + fmt)) return 'buyer';
  if (/tutorial|setup|review|walkthrough|deep/.test(lane + ' ' + fmt)) return 'authority';
  return 'experiment';
}

const normalized = rows.map((r, idx) => {
  const topic = norm(r.topic || r.Topic || '');
  const title = norm(r.title || r.Title || '');
  const status = norm(r.status || r.Status || '').toUpperCase();
  const score = Number(r.finalBusinessScore || r.cashCowScore || r.realScore || r.RealScore || r.score || r.Score || 0);
  const views = Number(r.realViews || r.RealViews || r.views || r.Views || 0);
  const retention = Number(r.realAvgRetention || r.RealAvgRetention || r.avgRetention || r.AvgRetention || 0);
  const ctr = Number(r.thumbCtr || r.thumbnailCtr || r.videoThumbnailImpressionsClickRate || r.ctrPrediction || r.CtrPrediction || 0);
  const impressions = Number(r.thumbImpressions || r.thumbnailImpressions || r.videoThumbnailImpressions || 0);
  const watchMinutes = Number(r.realWatchMins || r.RealWatchMins || r.watchMinutes || r.WatchMinutes || 0);
  const hookType = norm(r.hookType || r.HookType || '');
  const format = norm(r.selectedFormat || r.format || r.videoFormat || r.VideoFormat || '');
  const lane = norm(r.contentLane || r.ContentLane || '');
  const titleStarter = title.split(/[:\-]/)[0].slice(0, 30);
  const created = new Date(r.date || r.Date || r.publishedAt || r.PublishedAt || 0).getTime() || (Date.now() - idx * 86400000);
  return {
    topic,
    title,
    status,
    score,
    views,
    retention,
    ctr,
    impressions,
    watchMinutes,
    hookType,
    format,
    lane,
    titleStarter,
    buyerIntentScore: Number(r.buyerIntentScore || r.BuyerIntentScore || 0),
    firstDollarScore: Number(r.firstDollarScore || r.FirstDollarScore || 0),
    audienceOwnershipScore: Number(r.audienceOwnershipScore || r.AudienceOwnershipScore || 0),
    authenticityScore: Number(r.authenticityScore || r.AuthenticityScore || 0),
    sequelDepthScore: Number(r.sequelDepthScore || r.SequelDepthScore || 0),
    monetizationFit: norm(r.monetizationFit || r.MonetizationFit || ''),
    primaryKeyword: norm(r.primaryKeyword || r.PrimaryKeyword || ''),
    mixBucket: inferMixBucket(r),
    created
  };
}).sort((a,b) => b.created - a.created);

const publishedOnly = normalized.filter(r => r.status === 'PUBLISHED' || r.status === 'READY_TO_RENDER' || r.status === 'DRAFT_SAVED');
const recentPublished = publishedOnly.slice(0, 20);

const recent7 = publishedOnly.slice(0, 7);
const prev7 = publishedOnly.slice(7, 14);
const winnerFn = (r) => r.score >= 8 || (r.views >= 500 && r.retention >= 38 && r.ctr >= 4.2);
const loserFn = (r) => (r.views > 0 && r.views < 120) || (r.retention > 0 && r.retention < 24) || (r.ctr > 0 && r.ctr < 2.6);

const recentWinRate = recent7.length ? Math.round(100 * recent7.filter(winnerFn).length / recent7.length) : 0;
const prevWinRate = prev7.length ? Math.round(100 * prev7.filter(winnerFn).length / prev7.length) : 0;
const winTrend = recentWinRate > prevWinRate ? 'IMPROVING' : recentWinRate < prevWinRate ? 'DECLINING' : 'STABLE';

function scoreGroups(entries, keyFn) {
  const groups = {};
  for (const r of entries) {
    const key = keyFn(r);
    if (!key) continue;
    groups[key] = groups[key] || { key, count: 0, winners: 0, avgCtr: 0, avgRetention: 0, avgViews: 0, weightedScore: 0 };
    const g = groups[key];
    g.count += 1;
    g.winners += winnerFn(r) ? 1 : 0;
    g.avgCtr += r.ctr;
    g.avgRetention += r.retention;
    g.avgViews += r.views;
    g.weightedScore += (r.score * 0.5) + (r.ctr * 0.25) + (r.retention * 0.10) + (Math.min(r.views, 3000) / 3000 * 10 * 0.15);
  }
  return Object.values(groups).map(g => ({
    key: g.key,
    count: g.count,
    winRate: Number((g.winners / Math.max(g.count, 1)).toFixed(2)),
    avgCtr: Number((g.avgCtr / Math.max(g.count, 1)).toFixed(1)),
    avgRetention: Number((g.avgRetention / Math.max(g.count, 1)).toFixed(1)),
    avgViews: Math.round(g.avgViews / Math.max(g.count, 1)),
    weightedScore: Number((g.weightedScore / Math.max(g.count, 1)).toFixed(2))
  })).sort((a,b) => b.weightedScore - a.weightedScore).slice(0, 5);
}

const bestHookTypes = scoreGroups(publishedOnly.filter(r => r.hookType), r => r.hookType);
const bestFormatFamilies = scoreGroups(publishedOnly.filter(r => r.format), r => r.format);
const bestContentLanes = scoreGroups(publishedOnly.filter(r => r.lane), r => r.lane);
const bestTitleStarters = scoreGroups(publishedOnly.filter(r => r.titleStarter), r => r.titleStarter);
const topKeywords = scoreGroups(publishedOnly.filter(r => r.primaryKeyword), r => r.primaryKeyword);

const mixWindow = recentPublished.slice(0, 10);
const mixCounts = { buyer: 0, authority: 0, experiment: 0 };
for (const row of mixWindow) mixCounts[row.mixBucket] = (mixCounts[row.mixBucket] || 0) + 1;
const mixTotal = Math.max(mixWindow.length, 1);
const mixNow = {
  buyer: Number((mixCounts.buyer / mixTotal).toFixed(2)),
  authority: Number((mixCounts.authority / mixTotal).toFixed(2)),
  experiment: Number((mixCounts.experiment / mixTotal).toFixed(2))
};
const targets = cfg.moneyMixTargets || { buyer: 0.7, authority: 0.2, experiment: 0.1 };
const underusedWinningLanes = bestContentLanes
  .filter(x => x.weightedScore >= 7.5 && !mixWindow.some(r => lower(r.lane) === lower(x.key)))
  .map(x => x.key)
  .slice(0, 3);

const contentMixRecommendation = [
  `Buyer-intent evergreen: ${Math.round((targets.buyer || 0.7) * 100)}%`,
  `Authority/trust: ${Math.round((targets.authority || 0.2) * 100)}%`,
  `Experiments: ${Math.round((targets.experiment || 0.1) * 100)}%`
].join(' | ');

const mixWarnings = [];
if (mixNow.buyer < (targets.buyer || 0.7) - 0.15) mixWarnings.push('Increase buyer-intent videos');
if (mixNow.authority < (targets.authority || 0.2) - 0.10) mixWarnings.push('Add one authority/tutorial video');
if (mixNow.experiment > (targets.experiment || 0.1) + 0.10) mixWarnings.push('Reduce experiments until winners improve');

const topGapIdeas = (cfg.gapIdeasSeed || []).slice(0, 6);
const offerCatalogSummary = (cfg.offerCatalog || []).map(o => `${o.label} (${o.type})`).slice(0, 5);

const selfAdjustment = winTrend === 'DECLINING'
  ? 'Tighten to the top hook, format, and lane. Reduce experiments for the next 5 uploads.'
  : winTrend === 'IMPROVING'
  ? 'Double down on current winners and spin the best topic into sequels.'
  : 'Stay near the winning lanes and keep a small test budget for fresh angles.';

const pastTitles = unique(recentPublished.map(r => r.title));
const pastHooks = unique(recentPublished.map(r => r.hookType));
const avoidTopics = unique(recentPublished.map(r => r.topic)).slice(0, 20);

const strategyBrief = [
  `Win trend: ${winTrend}. Recent 7-video win rate: ${recentWinRate}% vs previous ${prevWinRate}%.`,
  `Best hook types: ${bestHookTypes.slice(0,3).map(x => x.key).join(', ') || 'none yet'}.`,
  `Best formats: ${bestFormatFamilies.slice(0,3).map(x => x.key).join(', ') || 'none yet'}.`,
  `Best content lanes: ${bestContentLanes.slice(0,3).map(x => x.key).join(', ') || 'none yet'}.`,
  `Money mix target: ${contentMixRecommendation}. Current mix: buyer ${Math.round(mixNow.buyer*100)}%, authority ${Math.round(mixNow.authority*100)}%, experiment ${Math.round(mixNow.experiment*100)}%.`,
  mixWarnings.length ? `Mix warnings: ${mixWarnings.join('; ')}.` : 'Mix is roughly on target.',
  underusedWinningLanes.length ? `Underused winning lanes: ${underusedWinningLanes.join(', ')}.` : 'No underused winning lanes detected.',
  topKeywords.length ? `Top keywords: ${topKeywords.slice(0,3).map(x => x.key).join(', ')}.` : 'No keyword winners yet.',
  topGapIdeas.length ? `Gap ideas to consider: ${topGapIdeas.join(' | ')}.` : '',
  offerCatalogSummary.length ? `Available offer stack: ${offerCatalogSummary.join('; ')}.` : '',
  activeNotes.length ? `Owner notes: ${activeNotes.join(' | ')}.` : ''
].filter(Boolean).join('\n');

return [{
  json: {
    ...cfg,
    recentWinRate,
    prevWinRate,
    winTrend,
    selfAdjustment,
    ownerNotesCount: activeNotes.length,
    ownerNotesApplied: activeNotes,
    bestHookTypes,
    bestFormatFamilies,
    bestContentLanes,
    bestTitleStarters,
    topKeywords,
    pastTitles,
    pastHooks,
    recentPublished: recentPublished.map(r => ({
      topic: r.topic,
      title: r.title,
      status: r.status,
      score: r.score,
      contentLane: r.lane,
      monetizationFit: r.monetizationFit
    })),
    avoidTopics,
    gapIdeasSeed: topGapIdeas,
    offerCatalog: cfg.offerCatalog || [],
    offerCatalogSummary,
    contentMixNow: mixNow,
    contentMixRecommendation,
    underusedWinningLanes,
    strategyBrief
  }
}];

parameters.jsonBody:
={{ {
  model: $json.groqModel || 'llama-3.3-70b-versatile',
  messages: [
    {
      role: 'system',
      content: `You are the strategy brain for a faceless YouTube channel. Return ONLY valid JSON with these keys:
topic, whyThisWillWork, competitorGap, contentGapAngle, mainPainPoint, score, projectedRoi, originalityScore, trustScore, evergreenScore, followupPotential, riskScore, searchIntentScore, searchDemand, buyerIntent, buyerIntentScore, firstDollarScore, audienceOwnershipScore, authenticityScore, sequelDepthScore, sponsorSafetyScore, monetizationFit, primaryOfferType, regularViewerFit, thumbnailPrompt, longVideo, shorts.

Rules:
- Pick a topic with clear search demand and money potential.
- Avoid fake urgency, fear tactics, and generic guru language.
- Include one honest limitation or tradeoff in the script.
- Make the video feel original, useful, and specific.
- Use one clear next step, not a pile of offers.
- longVideo must contain title, hook, script, cta.
- shorts must be an array with exactly ${$json.shortCount || 1} entries.
- Keep title under 60 characters.
- Make scripts helpful enough to rank and commercially useful enough to monetize.
- Favor concrete local-service business use cases, clear before/after outcomes, and simple stack choices.
- Mention the business type, the software being replaced, the monthly cost/time pain, and the one main tradeoff.
- Bias toward broad but buyer-intent topics: free-vs-paid, replace-X, cheaper stack, or 3-app consolidation.
- Open the long video with the cost problem in the first 15 seconds.`
    },
    {
      role: 'user',
      content: `${$json.strategyBrief}

Niche: ${$json.niche}
Keywords: ${$json.nicheKeywords}
Avoid topics: ${($json.avoidTopics || []).join(' | ')}
Gap ideas: ${($json.gapIdeasSeed || []).join(' | ')}
Offer stack: ${(Array.isArray($json.offerCatalogSummary) ? $json.offerCatalogSummary.join(' | ') : '')}
Audience: ${$json.targetAudience || ''}
Content lanes: ${($json.contentLanes || []).join(' | ')}
Money mix: ${JSON.stringify($json.moneyMixTargets || {})}
Date: ${new Date().toISOString().slice(0,10)}

Return JSON only.`
    }
  ],
  temperature: 0.55,
  max_tokens: 4000
} }}

parameters.jsCode:
const j = items[0].json || {};
const prev = $('Competitive Intelligence + Owner Notes Engine').first().json || {};
let raw = '';
try { raw = j.choices?.[0]?.message?.content || ''; } catch(e) {}
let data = null;
let parseError = '';
try { data = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); } catch(e) { parseError = 'Parse: ' + e.message; }

if (!data) {
  return [{ json: { ...prev, status:'PARSE_FAILED', errorStep:'Research', errorMessage:parseError || 'No JSON returned', needsIntervention:true, timestamp:new Date().toISOString() } }];
}

const clamp = (n, fallback=0) => {
  const v = Number(n);
  if (Number.isFinite(v)) return Math.max(0, Math.min(10, v));
  return fallback;
};

const textLevelMap = { high: 8.8, medium: 7.2, low: 5.6 };
const longVideo = data.longVideo || {};
const errors = [];

if ((prev.runType || '').toUpperCase() !== 'SHORTS_ONLY') {
  if (!longVideo.script || String(longVideo.script).length < 350) errors.push('Script short');
  if (!longVideo.title || String(longVideo.title).length < 10) errors.push('Title missing');
}
if (!data.topic) errors.push('No topic');

const requiredShorts = Number(prev.shortCount || 1);
if (!Array.isArray(data.shorts) || data.shorts.length < requiredShorts) errors.push(`Need ${requiredShorts}+ shorts`);

const score = clamp(data.score, 0);
const projectedRoi = clamp(data.projectedRoi || data.projectedROI, 8);
const originalityScore = clamp(data.originalityScore || data.uniquenessScore, 8);
const trustScore = clamp(data.trustScore, 8);
const evergreenScore = clamp(data.evergreenScore, 8);
const followupPotential = clamp(data.followupPotential, 8);
const riskScore = clamp(data.riskScore, 1.5);
const searchIntentScore = clamp(data.searchIntentScore, 8);
const buyerIntentScore = clamp(data.buyerIntentScore, textLevelMap[String(data.buyerIntent || 'medium').toLowerCase()] || 7.2);
const firstDollarScore = clamp(data.firstDollarScore, buyerIntentScore - 0.2);
const audienceOwnershipScore = clamp(data.audienceOwnershipScore, 7.0);
const authenticityScore = clamp(data.authenticityScore, 8.0);
const sequelDepthScore = clamp(data.sequelDepthScore, 8.0);
const sponsorSafetyScore = clamp(data.sponsorSafetyScore, 8.2);
const searchDemandScore = clamp(data.searchDemandScore, textLevelMap[String(data.searchDemand || 'medium').toLowerCase()] || 7.2);

if (score < Number(prev.minScoreToPublish || 6)) errors.push(`Score ${score} < minimum`);
if (originalityScore < Number(prev.minOriginalityScore || 7.5)) errors.push('Originality too low');
if (trustScore < Number(prev.minTrustScore || 8)) errors.push('Trust score too low');
if (evergreenScore < Number(prev.minEvergreenScore || 7)) errors.push('Evergreen score too low');
if (followupPotential < Number(prev.minFollowupPotential || 7)) errors.push('Follow-up potential too low');
if (projectedRoi < Number(prev.minProjectedRoi || 7)) errors.push('Projected ROI too low');
if (riskScore > Number(prev.maxRiskScore || 2)) errors.push('Risk score too high');
if (searchIntentScore < Number(prev.minSearchIntentScore || 7.5)) errors.push('Search intent too low');
if (buyerIntentScore < Number(prev.minBuyerIntentNumericScore || 7)) errors.push('Buyer intent too low');
if (firstDollarScore < Number(prev.minFirstDollarScore || 6.8)) errors.push('First-dollar speed too low');
if (audienceOwnershipScore < Number(prev.minAudienceOwnershipScore || 6.2)) errors.push('Audience ownership score too low');
if (authenticityScore < Number(prev.minAuthenticityScore || 7.5)) errors.push('Authenticity score too low');
if (sequelDepthScore < Number(prev.minSequelDepthScore || 7.0)) errors.push('Sequel depth too low');
if (sponsorSafetyScore < Number(prev.minSponsorSafetyScore || 7.0)) errors.push('Sponsor safety too low');

if (errors.length) {
  return [{ json: {
    ...prev,
    status:'VALIDATION_FAILED',
    errorStep:'Validation',
    errorMessage: errors.join('; '),
    needsIntervention:false,
    topic:data.topic || '',
    score,
    buyerIntentScore,
    firstDollarScore,
    audienceOwnershipScore,
    authenticityScore,
    sequelDepthScore,
    sponsorSafetyScore,
    timestamp:new Date().toISOString()
  } }];
}

const cashCowPreScore = Number(((score*0.22)+(projectedRoi*0.12)+(buyerIntentScore*0.14)+(firstDollarScore*0.12)+(audienceOwnershipScore*0.10)+(authenticityScore*0.10)+(sequelDepthScore*0.10)+(searchIntentScore*0.10)).toFixed(1));

return [{
  json: {
    ...prev,
    status:'READY_FOR_SEO',
    topic:data.topic,
    whyThisWillWork:data.whyThisWillWork || '',
    competitorGap:data.competitorGap || '',
    contentGapAngle:data.contentGapAngle || '',
    mainPainPoint:data.mainPainPoint || '',
    regularViewerFit:data.regularViewerFit || 'medium',
    score,
    projectedRoi,
    originalityScore,
    trustScore,
    evergreenScore,
    followupPotential,
    riskScore,
    searchIntentScore,
    searchDemand:data.searchDemand || 'medium',
    searchDemandScore,
    buyerIntent:data.buyerIntent || 'medium',
    buyerIntentScore,
    firstDollarScore,
    audienceOwnershipScore,
    authenticityScore,
    sequelDepthScore,
    sponsorSafetyScore,
    monetizationFit:data.monetizationFit || 'affiliate',
    primaryOfferType:data.primaryOfferType || '',
    thumbnailPrompt:data.thumbnailPrompt || '',
    longVideoTitle:longVideo.title,
    longVideoHook:longVideo.hook || '',
    longVideoScript:longVideo.script || '',
    longVideoCta:longVideo.cta || '',
    shorts:Array.isArray(data.shorts) ? data.shorts : [],
    scriptWordCount:(String(longVideo.script || '').trim().split(/\s+/).filter(Boolean).length),
    cashCowPreScore,
    needsIntervention:false,
    timestamp:new Date().toISOString()
  }
}];

