parameters.jsCode:
const j = items[0].json || {};
const prev = $('Parse + Validate').first().json || {};
if (prev.status !== 'READY_FOR_SEO') return [{ json: prev }];

let seo = null;
try {
  seo = JSON.parse(String(j.choices?.[0]?.message?.content || '').replace(/```json|```/g, '').trim());
} catch (e) {}

if (!seo) {
  seo = {
    optimizedTitle: prev.longVideoTitle,
    titleVariantB: prev.longVideoTitle,
    titleVariantC: prev.longVideoTitle,
    optimizedDescription: prev.longVideoTitle + '\n\n' + (prev.longVideoCta || 'Subscribe for the next one.'),
    primaryKeyword: prev.topic,
    secondaryKeywords: [],
    longTailKeywords: [],
    tags: ['local business software', 'AI automation', 'cheap CRM', 'service business tools'],
    hashtags: ['#SmallBusinessAI', '#LocalBusinessTools', '#Automation'],
    thumbnailBrief: {
      text: (prev.longVideoTitle || '').split(' ').slice(0, 4).join(' ').toUpperCase(),
      emotion: 'clarity',
      colorScheme: 'high contrast dark background',
      layout: 'left text right visual'
    },
    pinnedComment: '',
    endScreenText: '',
    timestamps: [],
    ctrPrediction: 7.0,
    searchVolume: 'medium',
    competition: 'medium',
    rankDifficulty: 'medium',
    seoScore: 7.4,
    optimizationNotes: 'Fallback SEO package',
    suggestedPostingTime: '',
    relatedVideoIdeas: [],
    offerAngle: 'one clear next step',
    newsletterAngle: 'simple follow-up resource'
  };
}

const cfg = $('Channel Config').first().json || prev;
const titleA = seo.optimizedTitle || prev.longVideoTitle;
const titleB = seo.titleVariantB || titleA;
const titleC = seo.titleVariantC || titleA;
const timestamps = Array.isArray(seo.timestamps) ? seo.timestamps : [];
let description = seo.optimizedDescription || prev.longVideoTitle + '\n\n' + (prev.longVideoCta || '');
if (timestamps.length && !description.includes('0:00')) description += '\n\n' + timestamps.join('\n');
const hashtags = Array.isArray(seo.hashtags) && seo.hashtags.length ? seo.hashtags : ['#AItools', '#Automation'];
if (!description.includes('#')) description += '\n\n' + hashtags.join(' ');
const tags = [...new Set([...(seo.tags || []), ...(seo.secondaryKeywords || []), ...(seo.longTailKeywords || [])])].filter(Boolean).slice(0, 15);

function slugify(input = '') {
  return String(input || '')
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-')
    .slice(0, 72);
}

function titleScore(t = '') {
  const s = String(t || '');
  let score = 6.0;
  if (s.length >= 35 && s.length <= 60) score += 1.0;
  if (/vs|how to|free|best|replace|automate|worth|alternative|cheaper/i.test(s)) score += 1.0;
  if (/\d/.test(s)) score += 0.3;
  if (!/(crazy|insane|shocking|secret)/i.test(s)) score += 0.2;
  return Math.min(10, Number(score.toFixed(1)));
}

function pickOffer(offers, payload) {
  const cleanOffers = Array.isArray(offers) ? offers.filter(Boolean) : [];
  const topic = String(payload.topic || '').toLowerCase();
  const lane = String(payload.contentLane || '').toLowerCase();
  const desiredType = String(payload.primaryOfferType || '').toLowerCase();
  if (!cleanOffers.length) return null;
  const scored = cleanOffers.map((offer, idx) => {
    const fit = Array.isArray(offer.fit) ? offer.fit.map(f => String(f).toLowerCase()) : [];
    let score = Number(offer.priority || 1);
    if (desiredType && String(offer.type || '').toLowerCase().includes(desiredType)) score += 3;
    if (fit.some(f => lane.includes(f) || topic.includes(f))) score += 2;
    if (/comparison|affiliate|winner/i.test(String(payload.monetizationFit || '')) && /comparison|winner|tool-stack/.test(String(offer.type || ''))) score += 2;
    if (/tutorial|template/i.test(String(payload.monetizationFit || '')) && /template|checklist|guide/.test(String(offer.type || ''))) score += 2;
    if (/template|checklist/.test(String(offer.type || '')) && /setup|how to|automate/i.test(topic + ' ' + titleA)) score += 1.5;
    return { ...offer, score, idx };
  }).sort((a, b) => b.score - a.score);
  return scored[0] || cleanOffers[0];
}

function resolveOfferUrl(offer, payload, cfg) {
  if (!offer) return '';
  const explicit = String(offer.url || '').trim();
  if (explicit && !explicit.includes('PASTE_')) return explicit;

  const base = String(cfg.offerBaseUrl || '').replace(/\/+$/, '');
  if (!base || base.includes('PASTE_')) return '';

  const topicSlug = slugify(payload.topic || payload.longVideoTitle || payload.primaryKeyword || 'resource');
  const titleSlug = slugify(payload.longVideoTitle || payload.topic || 'resource');
  const lane = String(payload.contentLane || '').toLowerCase();
  const kind = String(offer.type || '').toLowerCase();

  let path = String(cfg.offerBasePath || '/resources');
  if (/template|checklist|guide/.test(kind)) path = String(cfg.templateBasePath || '/templates');
  if (/comparison|winner/.test(kind) || /vs|alternative|worth|paid|free/i.test(titleA)) path = String(cfg.comparisonBasePath || '/compare');
  if (/tool-stack/.test(kind)) path = String(cfg.toolStackBasePath || '/stack');
  if (/guide/.test(kind) || /setup|tutorial|automate/i.test(lane + ' ' + titleA)) path = String(cfg.guideBasePath || '/guides');

  const slug = /comparison|winner/.test(kind) ? titleSlug : topicSlug;
  return `${base}${path}/${slug}`;
}

function addUtm(url, source = 'youtube', medium = 'organic', campaign = '') {
  if (!url) return '';
  const glue = url.includes('?') ? '&' : '?';
  const campaignSafe = slugify(campaign || titleA || prev.topic || 'channel');
  return `${url}${glue}utm_source=${source}&utm_medium=${medium}&utm_campaign=${campaignSafe}`;
}

const selectedOffer = pickOffer(prev.offerCatalog || cfg.offerCatalog || [], prev);
const rawOfferUrl = resolveOfferUrl(selectedOffer, prev, cfg);
const offerUrl = addUtm(rawOfferUrl, 'youtube', 'organic', titleA);
const offerLabel = selectedOffer?.label || '';
const offerType = selectedOffer?.type || '';
const offerCta = selectedOffer?.cta || (offerLabel ? `See ${offerLabel}` : 'Get the resource');
const oneLinkOfferPageTitle = offerLabel ? `${offerLabel} — best next step after this video` : '';
const offerLine = offerUrl ? `${offerCta}: ${offerUrl}` : '';

const thumbText = seo.thumbnailBrief?.text || titleA.split(' ').slice(0, 4).join(' ').toUpperCase();
const thumbEmotion = seo.thumbnailBrief?.emotion || 'clarity';
const thumbColors = seo.thumbnailBrief?.colorScheme || 'high contrast';
const thumbLayout = seo.thumbnailBrief?.layout || 'left text, right visual';
const basePrompt = prev.thumbnailPrompt || `YouTube thumbnail for ${titleA}.`;

const promptCandidates = [
  {
    label: 'A',
    angle: 'outcome-first',
    score: 8.4,
    prompt: `${basePrompt} Scene focuses on the end result. Use ${thumbColors}. ${thumbLayout}. Big simple visual outcome. No faces. Minimal clutter.`
  },
  {
    label: 'B',
    angle: 'comparison',
    score: 8.2,
    prompt: `${basePrompt} Create a side-by-side comparison visual with one clear winner. Use ${thumbColors}. Add space for short bold text: ${thumbText}. No faces.`
  },
  {
    label: 'C',
    angle: 'manual-vs-smart',
    score: 7.9,
    prompt: `${basePrompt} Show manual approach versus smart approach. Clean split composition. ${thumbColors}. Add a strong central object and simple arrows. No faces.`
  }
];

if ((prev.contentLane || '').includes('free') || /free|paid|worth|alternative/i.test(titleA)) promptCandidates[1].score += 0.5;
if ((prev.contentLane || '').includes('automation') || /automate|workflow|manual/i.test(titleA)) promptCandidates[2].score += 0.5;
if (offerUrl) promptCandidates[0].score += 0.1;
promptCandidates.sort((a, b) => b.score - a.score);

const ctrPrediction = Number(seo.ctrPrediction || 7.0);
const seoScore = Number(seo.seoScore || 7.4);
const packagingScore = Math.min(10, Number(((ctrPrediction * 0.45) + (seoScore * 0.35) + (titleScore(titleA) * 0.20)).toFixed(1)));
const thumbnailScore = Math.min(10, Number((promptCandidates[0].score + (ctrPrediction * 0.15)).toFixed(1)));
const offerCoverageScore = offerUrl ? 9.2 : 5.4;
const opsSimplicityScore = Math.min(10, Number((8.4 + (offerUrl ? 0.4 : 0) + (promptCandidates.length === 3 ? 0.2 : 0)).toFixed(1)));
const cashCowScore = Math.min(10, Number(((prev.cashCowPreScore || 7.5) * 0.47 + packagingScore * 0.18 + seoScore * 0.10 + thumbnailScore * 0.12 + offerCoverageScore * 0.08 + opsSimplicityScore * 0.05).toFixed(1)));

const relatedVideoIdeas = Array.isArray(seo.relatedVideoIdeas) ? seo.relatedVideoIdeas.filter(Boolean).slice(0, 5) : [];
const sequelIdeas = relatedVideoIdeas.length ? relatedVideoIdeas : [
  `${titleA} for beginners`,
  `${prev.topic} mistakes to avoid`,
  `${prev.topic} cheaper/free version`
];

const assetPlan = [
  {
    assetType: /comparison|winner/.test(offerType) || /vs|alternative|worth|paid|free/i.test(titleA) ? 'comparison-page' : /template|checklist|guide/.test(offerType) ? 'template-page' : 'resource-page',
    label: offerLabel || 'Primary resource',
    url: rawOfferUrl || '',
    cta: offerCta
  },
  {
    assetType: 'pinned-comment',
    label: 'Pinned comment CTA',
    url: offerUrl || '',
    cta: offerCta
  }
].filter(a => a.url || a.assetType === 'pinned-comment');

const oneLinkPinnedComment = seo.pinnedComment
  ? `${String(seo.pinnedComment).slice(0, 220)}${offerLine ? '\n\n' + offerLine : ''}`
  : offerLine
    ? `${titleA} was built to solve one clear problem. ${offerLine}\n\nWhat should the next video compare or automate?`
    : `What should the next video compare or automate?`;

const descriptionWithOffer = offerLine ? `${description}\n\n${offerLine}` : description;
const endScreenText = seo.endScreenText || `Next: ${sequelIdeas[0] || 'the next workflow breakdown'}`;
const offerSetupNeeded = !offerUrl;
const offerReadiness = offerUrl ? 'READY' : 'NEEDS_BASE_URL';

return [{
  json: {
    ...prev,
    status: 'READY_TO_RENDER',
    seoOptimized: true,
    seoTitle: titleA,
    seoTitleB: titleB,
    seoTitleC: titleC,
    longVideoTitle: titleA,
    description: descriptionWithOffer,
    seoDescription: descriptionWithOffer,
    primaryKeyword: seo.primaryKeyword || prev.topic,
    secondaryKeywords: Array.isArray(seo.secondaryKeywords) ? seo.secondaryKeywords : [],
    longTailKeywords: Array.isArray(seo.longTailKeywords) ? seo.longTailKeywords : [],
    tags,
    hashtags,
    thumbnailText: thumbText,
    thumbnailEmotion: thumbEmotion,
    thumbnailLayout: thumbLayout,
    ctrPrediction,
    searchVolume: seo.searchVolume || 'medium',
    competition: seo.competition || 'medium',
    rankDifficulty: seo.rankDifficulty || 'medium',
    seoScore,
    packagingScore,
    thumbnailScore,
    titleScore: titleScore(titleA),
    offerCoverageScore,
    opsSimplicityScore,
    optimizationNotes: seo.optimizationNotes || '',
    suggestedPostingTime: seo.suggestedPostingTime || '',
    relatedVideoIdeas,
    sequelIdeas,
    pinnedComment: oneLinkPinnedComment.slice(0, 350),
    endScreenText,
    thumbnailPromptCandidates: promptCandidates,
    selectedThumbnailPrompt: promptCandidates[0].prompt,
    oneLinkOfferLabel: offerLabel,
    oneLinkOfferUrl: offerUrl,
    oneLinkOfferUrlRaw: rawOfferUrl,
    oneLinkOfferType: offerType,
    oneLinkOfferCta: offerCta,
    oneLinkOfferPageTitle,
    offerSetupNeeded,
    offerReadiness,
    offerAngle: seo.offerAngle || '',
    newsletterAngle: seo.newsletterAngle || '',
    offerAssetPlan: assetPlan,
    cashCowScore
  }
}];

const j = items[0].json || {};
const cfg = $('Channel Config').first().json;

if (j.status !== 'READY_TO_RENDER' && j.status !== 'READY_FOR_SEO') return [{ json: j }];

const errors = [];
const normalize = (s='') => String(s).toLowerCase().replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();
const tokens = (s='') => new Set(normalize(s).split(' ').filter(w => w.length > 2));
const overlap = (a,b) => {
  const A = tokens(a), B = tokens(b);
  if (!A.size || !B.size) return 0;
  let inter = 0;
  for (const t of A) if (B.has(t)) inter++;
  return inter / Math.max(A.size, B.size);
};

const title = j.longVideoTitle || j.seoTitle || '';
const hook = j.longVideoHook || '';
const script = (j.longVideoScript || '').slice(0, 3000);
const titleLower = normalize(title);
const scriptLower = normalize(script);

const searchDemand = String(j.searchDemand || 'medium').toLowerCase();
const buyerIntent = String(j.buyerIntent || 'medium').toLowerCase();
if (searchDemand === 'low') errors.push('Search demand too low');
if (buyerIntent === 'low' && j.videoFormat === 'TOOL_COMPARISON') errors.push('Buyer intent too low for comparison');
if (Number(j.evergreenScore || 0) < Number(cfg.minEvergreenScore || 7.0)) errors.push('Not evergreen enough');
if (Number(j.followupPotential || 0) < Number(cfg.minFollowupPotential || 7.0)) errors.push('Low follow-up potential');
if (Number(j.packagingScore || 0) < Number(cfg.minPackagingScore || 7.2)) errors.push('Packaging score too low');
if (Number(j.thumbnailScore || 0) < Number(cfg.minThumbnailScore || 7.0)) errors.push('Thumbnail score too low');
if (Number(j.titleScore || 0) < Number(cfg.minTitleScore || 7.2)) errors.push('Title score too low');
if (Number(j.score || 0) < Number(cfg.minQualityGateScore || 7.5)) errors.push('Core topic score too low');

const pastTitles = Array.isArray(j.pastTitles) ? j.pastTitles.slice(0, 50) : [];
const maxSimilarity = Math.max(0, ...pastTitles.map(t => overlap(title, t)));
if (maxSimilarity >= Number(cfg.duplicateTitleSimilarity || 0.45)) {
  errors.push('Title too similar to past upload (' + maxSimilarity.toFixed(2) + ')');
}

const pastHooks = Array.isArray(j.pastHooks) ? j.pastHooks.slice(0, 30) : [];
const hookSim = Math.max(0, ...pastHooks.map(h => overlap(hook, h)));
if (hookSim >= 0.55) errors.push('Hook too similar to recent video');

const titleKeywords = [...tokens(title)];
let titleWordsInScript = 0;
for (const w of titleKeywords) if (scriptLower.includes(w)) titleWordsInScript++;
const titleTruthScore = titleKeywords.length ? titleWordsInScript / titleKeywords.length : 1;
if (titleTruthScore < 0.4) errors.push('Title claim not well supported in script');

if (/(you wont believe|insane|crazy|shocking|secret hack|guaranteed|overnight)/i.test(title) || /(you wont believe|insane|crazy|shocking|secret hack|guaranteed|overnight)/i.test(hook)) {
  errors.push('Title or hook uses misleading language');
}

if (cfg.affiliateCapEnabled) {
  const recentPublished = Array.isArray(j.recentPublished) ? j.recentPublished : [];
  const last3 = recentPublished.slice(0, 3);
  const affCount = last3.filter(r =>
    String(r.monetizationFit || '').toLowerCase() === 'affiliate' ||
    String(r.contentLane || '').toLowerCase() === 'comparison'
  ).length;
  if (affCount >= Number(cfg.maxAffiliateVideosPerThree || 1) && j.videoFormat === 'TOOL_COMPARISON') {
    errors.push('Affiliate cap reached — switch this topic to tutorial angle');
  }
}

if (errors.length > 0) {
  return [{ json: {
    ...j,
    status: 'TRUTH_GATE_FAILED',
    errorStep: 'Title + Truth Gate',
    errorMessage: errors.join('; '),
    needsIntervention: false,
    titleTruthScore: Number(titleTruthScore.toFixed(2)),
    timestamp: new Date().toISOString()
  }}];
}

return [{ json: { ...j, truthGatePassed: true, titleTruthScore: Number(titleTruthScore.toFixed(2)) } }];

const j = items[0].json || {};
const cfg = $('Channel Config').first().json || {};

if (j.status !== 'READY_TO_RENDER') return [{ json: j }];

const script = String(j.longVideoScript || '');
const description = String(j.description || '');
const title = String(j.longVideoTitle || '');
const hook = String(j.longVideoHook || '');
const opening = script.split(/\s+/).slice(0, 130).join(' ');

const concreteSignals = [
  /\bfor example\b/i,
  /\bexample\b/i,
  /\bstep 1\b/i,
  /\bsetup\b/i,
  /\bworkflow\b/i,
  /\bminutes?\b/i,
  /\$\d+/,
  /\bcompare\b/i
].filter(rx => rx.test(script + ' ' + hook + ' ' + title)).length;

const openingSignals = [
  /\bhere is\b/i,
  /\bthis video\b/i,
  /\bin \d+ minutes?\b/i,
  /\bvs\b/i,
  /\bfree\b/i,
  /\bstop doing\b/i,
  /\bautomate\b/i,
  /\bworth it\b/i
].filter(rx => rx.test(hook + ' ' + opening + ' ' + title)).length;
const nicheSignals = [
  /contractor|salon|cleaner|med spa|realtor|plumber|electrician|roof(er|ing)|agency/i,
  /replace|cheaper|free alternative|stop paying|stack/i,
  /\$\d+|hours? per week|subscriptions?/i
].filter(rx => rx.test(title + ' ' + hook + ' ' + opening + ' ' + script)).length;

const downsideSignals = /(downside|limitation|tradeoff|not for everyone|skip this if|drawback|only worth it if)/i.test(script + ' ' + hook + ' ' + (j.whyThisWillWork || ''));
const urlMatches = [...new Set((description.match(/https?:\/\/\S+/g) || []).map(s => s.replace(/[)\],.]+$/, '')))];
const oneLinkOnly = urlMatches.length <= 1;
const hasOfferLink = Boolean(j.oneLinkOfferUrl && !String(j.oneLinkOfferUrl).includes('PASTE_'));
const repeatedSentences = (() => {
  const sentences = script.split(/[.!?]\s+/).map(s => s.trim().toLowerCase()).filter(s => s.length > 30);
  const seen = new Set();
  let dupes = 0;
  for (const s of sentences) {
    const key = s.slice(0, 80);
    if (seen.has(key)) dupes++;
    seen.add(key);
  }
  return dupes;
})();

const authenticityHeuristic = Math.max(0, Math.min(10, Number((
  (
    (Number(j.authenticityScore || 7.8) * 0.45) +
    (concreteSignals >= 3 ? 1.6 : concreteSignals >= 2 ? 1.0 : 0.25) +
    (downsideSignals ? 1.1 : 0) +
    (nicheSignals >= 2 ? 0.9 : nicheSignals >= 1 ? 0.4 : 0) +
    (oneLinkOnly ? 0.5 : -0.7) -
    (repeatedSentences > 2 ? 0.8 : 0)
  ).toFixed(1)
))));

const openingQualityScore = Math.max(0, Math.min(10, Number((
  (
    (Number(j.titleScore || 7.5) * 0.24) +
    (openingSignals >= 3 ? 3.3 : openingSignals >= 2 ? 2.5 : openingSignals >= 1 ? 1.5 : 0.5) +
    (nicheSignals >= 2 ? 1.0 : nicheSignals >= 1 ? 0.5 : 0) +
    (/^(here|if|stop|i|this|replace)\b/i.test(hook.trim()) ? 1.0 : 0.4) +
    (/\b(cheaper|free|replace|stack|stop paying)\b/i.test(opening + ' ' + hook) ? 1.3 : 0.5)
  ).toFixed(1)
))));

const offerCoverageScore = Math.max(0, Math.min(10, Number((
  (Number(j.offerCoverageScore || (hasOfferLink ? 9 : 5)) * 0.75) +
  (hasOfferLink ? 1.2 : 0) +
  (oneLinkOnly ? 0.5 : -0.5)
).toFixed(1))));

const opsSimplicityScore = Math.max(0, Math.min(10, Number((
  (Number(j.opsSimplicityScore || 8.0) * 0.70) +
  (oneLinkOnly ? 0.9 : -0.8) +
  (repeatedSentences === 0 ? 0.6 : repeatedSentences <= 2 ? 0.2 : -0.6)
).toFixed(1))));

const errors = [];
if (concreteSignals < 2) errors.push('Needs at least one concrete example and clearer setup details');
if (!downsideSignals) errors.push('Add one honest downside or tradeoff');
if (!oneLinkOnly) errors.push('Description should carry one clear next step, not multiple links');
if (authenticityHeuristic < Number(cfg.minAuthenticityScore || 7.5)) errors.push('Authenticity heuristic too low');
if (openingQualityScore < Number(cfg.minOpeningQualityScore || 7.4)) errors.push('Opening 30-second quality too low');
if (offerCoverageScore < Number(cfg.minOfferCoverageScore || 6.8)) errors.push('Offer coverage too weak for a cash-focused upload');

const finalBusinessScore = Math.min(10, Number(((
  Number(j.cashCowScore || 7.5) * 0.42 +
  Number(j.buyerIntentScore || 7.0) * 0.10 +
  Number(j.firstDollarScore || 7.0) * 0.10 +
  Number(j.audienceOwnershipScore || 7.0) * 0.08 +
  authenticityHeuristic * 0.10 +
  Number(j.sequelDepthScore || 7.5) * 0.05 +
  openingQualityScore * 0.08 +
  offerCoverageScore * 0.04 +
  opsSimplicityScore * 0.03
)).toFixed(1)));

if (finalBusinessScore < Number(cfg.minCashCowScore || 7.8)) errors.push('Final business score below target');
if (opsSimplicityScore < Number(cfg.minOpsSimplicityScore || 7.2)) errors.push('Workflow simplicity score below target');

if (errors.length) {
  return [{
    json: {
      ...j,
      status: 'TRUTH_GATE_FAILED',
      errorStep: 'Authenticity + Cash Gate',
      errorMessage: errors.join('; '),
      authenticityHeuristic,
      openingQualityScore,
      offerCoverageScore,
      opsSimplicityScore,
      finalBusinessScore,
      needsIntervention: false,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    ...j,
    authenticityGatePassed: true,
    authenticityHeuristic,
    openingQualityScore,
    offerCoverageScore,
    opsSimplicityScore,
    finalBusinessScore,
    businessSummary: `Cash score ${finalBusinessScore}/10 | opening ${openingQualityScore}/10 | buyer intent ${j.buyerIntentScore || 0}/10`,
    timestamp: new Date().toISOString()
  }
}];

