parameters.jsCode:
const cfg = $('Channel Config').first().json;
const j = items[0].json || {};
const monthlyLimit = Number(cfg.flikiMonthlyCredits || 600);
const warningThreshold = Number(cfg.flikiCreditWarningThreshold || 480);

let monthCreditsUsed = 0;
const thisMonth = new Date().toISOString().slice(0, 7);
try {
  const rows = $('Load Past Videos').all().map(i => i.json);
  const thisMonthRows = rows.filter(r => String(r.date || r.Date || '').startsWith(thisMonth));
  for (const r of thisMonthRows) {
    const status = String(r.status || r.Status || '').toUpperCase();
    if (status === 'PUBLISHED' || status === 'RENDERED') {
      const type = String(r.runType || r.videoFormat || r.VideoFormat || '');
      if (type.includes('COMPARISON') || type.includes('MONEY')) monthCreditsUsed += Number(cfg.estimatedCreditsPerLongVideo || 10);
      else if (type.includes('REVIEW') || type.includes('AUTHORITY')) monthCreditsUsed += Number(cfg.estimatedCreditsPerLongVideo || 10);
      if (String(r.shortTitle || r.ShortTitle || '').trim()) monthCreditsUsed += Number(cfg.estimatedCreditsPerShort || 1.25);
    }
  }
} catch(e) {}

const remaining = monthlyLimit - monthCreditsUsed;
const nearLimit = monthCreditsUsed >= warningThreshold;
const reserve = Number(cfg.reserveCreditsForWinners || 80);
const confidence = Number(j.packagingScore || j.score || 0);
const minConfidence = Number(cfg.minConfidenceToSpendCredits || 7.8);

if (remaining <= 0) {
  return [{ json: { ...j, status:'BUDGET_EXCEEDED', errorStep:'Budget Guard', errorMessage:`Fliki credits exhausted: ${monthCreditsUsed}/${monthlyLimit}`, needsIntervention:true, budgetUsed:monthCreditsUsed, budgetRemaining:remaining } }];
}

if (nearLimit && remaining <= reserve && confidence < minConfidence) {
  return [{ json: { ...j, status:'BUDGET_HOLD', skipVideoRender:true, errorStep:'Budget Guard', errorMessage:`Holding low-confidence render to preserve remaining credits (${remaining}) for stronger videos.`, needsIntervention:false, budgetUsed:monthCreditsUsed, budgetRemaining:remaining, budgetWarning:true } }];
}

return [{ json: { ...j, budgetUsed:monthCreditsUsed, budgetRemaining:remaining, budgetWarning:nearLimit, budgetOk:true } }];

const cfg = $('Channel Config').first().json;
const intel = $('Competitive Intelligence + Owner Notes Engine').first().json;

function weightedPick(entries, fallback = []) {
  if (!entries.length) return fallback[Math.floor(Math.random() * Math.max(fallback.length, 1))] || null;
  const exploit = Number(cfg.winnerPatternShare || 0.7);
  const secondary = Number(cfg.secondaryPatternShare || 0.2);
  const experiment = Number(cfg.experimentPatternShare || 0.1);
  const roll = Math.random();
  const sorted = [...entries].sort((a,b) => (b.weightedScore || 0) - (a.weightedScore || 0));
  if (roll <= exploit && sorted[0]) return sorted[0];
  if (roll <= exploit + secondary && sorted[1]) return sorted[1];
  const pool = sorted.slice(2);
  if (pool.length) return pool[Math.floor(Math.random() * pool.length)];
  return sorted[0] || null;
}

const hookWinner = weightedPick(intel.bestHookTypes || [], []);
const formatWinner = weightedPick(intel.bestFormatFamilies || [], []);
const laneWinner = weightedPick(intel.bestContentLanes || [], []);
const titleStarterWinner = weightedPick(intel.bestTitleStarters || [], []);

const hookType = hookWinner?.key || (cfg.hookLibrary?.[0] || 'RESULT_FIRST').split(':')[0];
const selectedHook = (cfg.hookLibrary || []).find(h => h.startsWith(hookType + ':')) || cfg.hookLibrary?.[0] || 'RESULT_FIRST: Start with the result.';
const selectedFormat = formatWinner?.key || (cfg.runType === 'MONEY_VIDEO' ? 'head-to-head comparison' : 'step-by-step walkthrough');
const contentLane = laneWinner?.key || (cfg.contentLanes || [])[0] || '';
const titleStarter = titleStarterWinner?.key || (cfg.preferredTitleStarters || [])[0] || '';
const expectedCtr = hookWinner?.avgCtr || 4.0;
const expectedRetention = formatWinner?.avgRetention || 36.0;

const reasonChosen = [
  hookWinner ? `Hook ${hookType} is a current winner` : `Hook ${hookType} chosen as fallback`,
  formatWinner ? `Format ${selectedFormat} has worked historically` : `Format ${selectedFormat} chosen from run type`,
  laneWinner ? `Lane ${contentLane} is in a strong pocket` : `Lane ${contentLane} chosen from config`
].join('; ');

return [{
  json: {
    ...items[0].json,
    hookType,
    selectedHook,
    selectedFormat,
    contentLane,
    preferredTitleStarter: titleStarter,
    expectedCtrBucket: expectedCtr >= 5 ? 'HIGH' : expectedCtr >= 3.5 ? 'MEDIUM' : 'LOW',
    expectedRetentionBucket: expectedRetention >= 42 ? 'HIGH' : expectedRetention >= 32 ? 'MEDIUM' : 'LOW',
    expectedCtr,
