const run = async () => {
  const cfg = $('Channel Config').first().json;
  const input = $input.first().json || {};
  const renderId = input.id || input.data?.id || input.jobId || '';
  if (!renderId) throw new Error('No Fliki short render id');

  const maxChecks = 22;
  let waitMs = 15000;
  let last = null;

  for (let i = 0; i < maxChecks; i++) {
    await new Promise((resolve) => setTimeout(resolve, waitMs));

    const res = await $http.request({
      method: 'GET',
      url: `https://api.fliki.ai/v1/generate/${renderId}`,
      headers: {
        Authorization: `Bearer ${cfg.flikiApiKey}`,
      },
    });

    last = res;
    const url =
      res.videoUrl ||
      res.video_url ||
      res.data?.videoUrl ||
      res.data?.video_url ||
      res.url ||
      res.output?.url ||
      '';

    if (url) {
      return [
        {
          json: {
            ...input,
            ...res,
            videoDownloadUrl: url,
            flikiComplete: true,
            renderId,
          },
        },
      ];
    }

    if (String(res.status || '').toLowerCase().includes('fail')) {
      throw new Error('Fliki short failed');
    }

    waitMs = Math.min(25000, waitMs + 2000);
  }

  throw new Error(`Fliki short timeout for render ${renderId}. Last status: ${JSON.stringify(last || {})}`);
};

return run();

