        },
      },
    ];
  }

  let last = null;

  for (let i = 0; i < 15; i++) {
    await new Promise((resolve) => setTimeout(resolve, 15000));

    const res = await $http.request({
      method: 'GET',
      url: `https://api.upload-post.com/api/uploadposts/status?request_id=${encodeURIComponent(requestId)}`,
      headers: {
        Authorization: `Apikey ${cfg.uploadPostApiKey}`,
      },
    });

    last = res;
    const status = String(res.status || '').toLowerCase();

    if (status === 'completed') {
      return [
        {
          json: {
            ...input,
            uploadPostStatus: 'completed',
            uploadPostResults: res.results || {},
          },
        },
      ];
    }

    if (status === 'failed') {
      return [
        {
          json: {
            ...input,
            uploadPostStatus: 'failed',
          },
        },
      ];
    }
  }

  return [
    {
      json: {
        ...input,
        uploadPostStatus: String(last?.status || 'timeout'),
      },
    },
  ];
};

return run();

