parameters.jsCode:
const j = $('Authenticity + Cash Gate').first().json || {};
if (j.status !== 'READY_TO_RENDER') return [{ json: j }];

const rows = $input.all().map(i => i.json || {});
const now = new Date();
const cfg = $('Channel Config').first().json || {};
const horizon = Number(cfg.dedupeWindowDays || 10);
const norm = (s='') => String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();
const toks = s => new Set(norm(s).split(' ').filter(w => w.length > 2));
const overlap = (a,b) => {
  const A=toks(a), B=toks(b);
  if (!A.size || !B.size) return 0;
  let hit=0;
  for (const t of A) if (B.has(t)) hit++;
  return hit / Math.max(A.size, B.size);
};

const currentFamily = String(j.topicFamily || j.sequelFamily || j.primaryKeyword || j.topic || '');
const currentTitle = String(j.longVideoTitle || '');
const currentKeyword = String(j.primaryKeyword || j.topic || '');
const currentChannel = String(j.channelName || '');

let duplicate = null;
for (const row of rows) {
  const rowDate = row.date || row.publishedAt || row.createdAt;
  if (!rowDate) continue;
  const days = (now - new Date(rowDate)) / 86400000;
  if (isNaN(days) || days > horizon) continue;
  const rowChannel = String(row.channelName || '');
  if (!rowChannel || rowChannel === currentChannel) continue;

  const familyHit = currentFamily && String(row.topicFamily || row.sequelFamily || row.primaryKeyword || '').toLowerCase() === currentFamily.toLowerCase();
  const keywordHit = currentKeyword && String(row.primaryKeyword || row.topic || '').toLowerCase() === currentKeyword.toLowerCase();
  const titleSim = overlap(currentTitle, row.title || row.longVideoTitle || '');
  const topicSim = overlap(currentFamily + ' ' + currentKeyword, String(row.topicFamily || '') + ' ' + String(row.primaryKeyword || row.topic || ''));

  if (familyHit || keywordHit || titleSim >= 0.62 || topicSim >= 0.72) {
    duplicate = { rowChannel, rowDate, title: row.title || row.longVideoTitle || '', titleSim: Number(titleSim.toFixed(2)), topicSim: Number(topicSim.toFixed(2)) };
    break;
  }
}

if (duplicate) {
  return [{
    json: {
      ...j,
      status: 'DUPLICATE_TOPIC',
      errorStep: 'Cross-Channel Dedupe Gate',
      errorMessage: `Too similar to recent ${duplicate.rowChannel} upload: ${duplicate.title}`.slice(0, 500),
      duplicateCrossChannel: true,
      duplicateWithChannel: duplicate.rowChannel,
      duplicateWithTitle: duplicate.title,
      duplicateTitleSimilarity: duplicate.titleSim,
      duplicateTopicSimilarity: duplicate.topicSim
    }
  }];
}

return [{ json: { ...j, crossChannelCheckPassed: true } }];
